sys_rte_eb_multi_in_script_operation.script:
(function (batch, output) {
   for (var i = 0; i < batch.length; i++) {
      var input = batch[i].input;
      var depIDs = input.split('|');
      var depSysIDs = [];
      for (var j = 0; j < depIDs.length; j++) {
         var numDep = depIDs[j];
         if(!numDep) continue;
         var depSysID = '';
         new global.GlideQuery('cmn_department')
         .where('id', numDep)
         .select(['id', 'u_active'])
         .forEach(function (dep) {
            // Associa o Departamento mesmo que não esteja ativo
            if (!depSysID) {
               depSysID = dep.sys_id + '';
            } else {
               if (dep.u_active) {
                  depSysID = dep.sys_id + '';
               }
            }
         });
         depSysIDs.push(depSysID);
      }
      output[i] = depSysIDs.join(',');
   }
})(batch, output);
